    "dashboard/",
    "# git worktrees for the reports and learnings orphan branches, and knowledge PRs",
    "reports-wt/",
    "learnings-wt/",
    "knowledge-wt/",
    "# contributions not published yet \u2014 machine-local until they reach the team repo",
    "pending-learnings/",
    "# report data lives on the teamai-reports orphan branch, not on main",
    "members/",
    "sessions/",
    "votes/",
    "stats/",
    "pending-review.jsonl",
    "",
