modelsCmd.command("add <id>").description("Add a personal model profile stored only on this machine").option("--name <name>", "Display name").option("--protocol <protocols>", "Comma-separated: anthropic, openai-chat-completions, openai-responses").option("--base-url <url>", "Gateway root URL (without /v1)").option("--model <ids>", "Comma-separated model IDs; the first is the default").option("--from-env <name>", "Read the API key from this environment variable").option("--api-key-stdin", "Read the API key from stdin without placing it in shell history").action((id, cmdOpts) => runModelsCommand((m) => m.modelsAdd(id, cmdOpts)));
modelsCmd.command("configure <profile>").description("Set the API key of a profile, or edit a personal profile").option("--from-env <name>", "Read the API key from this environment variable").option("--api-key-stdin", "Read the API key from stdin without placing it in shell history").option("--name <name>", "Personal profiles: new display name").option("--base-url <url>", "Personal profiles: new gateway root URL").option("--protocol <protocols>", "Personal profiles: serve models over these protocols too").option("--model <ids>", "Personal profiles: add model IDs").action((profile, cmdOpts) => runModelsCommand((m) => m.modelsConfigure(profile, cmdOpts)));
